def get_sentence_embedding(sentence, model):
    """
    Calculates embeddings for a sentence.
    """
    words = sentence.split()
    word_embeddings = [model[word] for word in words if word in model]

    if not word_embeddings:
        # returns a zero vector if all words are oov
        return np.zeros(model.vector_size)

    # average of word embeddings
    return np.mean(word_embeddings, axis=0)

# function to enumerate intent labels and assign unique IDs
def enumerate_intents(df_train, df_valid, df_test):
    unique_intents = df_train['intent'].unique()
    intent_label_to_id = {label: idx for idx, label in enumerate(unique_intents)}
    intent_id_to_label = {idx: label for label, idx in intent_label_to_id.items()}

    df_train.loc[:, 'intent_id'] = df_train['intent'].map(intent_label_to_id)
    df_valid.loc[:, 'intent_id'] = df_valid['intent'].map(intent_label_to_id)
    df_test.loc[:, 'intent_id'] = df_test['intent'].map(intent_label_to_id)

    return intent_label_to_id, intent_id_to_label

# function to enumerate slot labels and assign unique IDs
def enumerate_slots(df_train, df_valid, df_test):
    all_slot_labels = set(label for labels in df_train['slots'] for label in labels.split())
    slot_label_to_id = {label: idx for idx, label in enumerate(sorted(all_slot_labels))}
    slot_id_to_label = {idx: label for label, idx in slot_label_to_id.items()}

    df_train.loc[:, 'slot_ids'] = df_train['slots'].apply(lambda labels: [slot_label_to_id[label] for label in labels.split()])
    df_valid.loc[:, 'slot_ids'] = df_valid['slots'].apply(lambda labels: [slot_label_to_id[label] for label in labels.split()])
    df_test.loc[:, 'slot_ids'] = df_test['slots'].apply(lambda labels: [slot_label_to_id[label] for label in labels.split()])

    return slot_label_to_id, slot_id_to_label
